<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoPeriodo, guardarPeriodoContable, listarPeriodosContables, marcarPeriodoVigente, procesarPeriodo } from '../services/periodosContables'
import type { PeriodoContable, PeriodoContablePayload, ProcesoPeriodoPayload } from '../interfaces/periodosContables.interface'

const rows=ref<PeriodoContable[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),processModal=ref(false),editing=ref<number|null>(null),selected=ref<PeriodoContable|null>(null),action=ref<'aperturar'|'cerrar'>('aperturar')
const form=reactive<PeriodoContablePayload>({codigo:'',descripcion:''})
const processForm=reactive<ProcesoPeriodoPayload>({generar_asiento:false,fecha:new Date().toISOString().slice(0,10),glosa:''})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarPeriodosContables(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:PeriodoContable){editing.value=item?.id??null;form.codigo=item?.codigo??'';form.descripcion=item?.descripcion??'';modal.value=true;error.value=''}
async function save(){if(!form.codigo.trim()||!form.descripcion.trim())return void(error.value='Complete el código y la descripción.');saving.value=true;try{await guardarPeriodoContable(editing.value,{codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim()});modal.value=false;success.value=`Periodo ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:PeriodoContable){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} el periodo ${item.codigo}?`))return;try{await cambiarEstadoPeriodo(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
async function current(item:PeriodoContable){if(!confirm(`¿Marcar ${item.codigo} como periodo vigente?`))return;try{await marcarPeriodoVigente(item.id);success.value='Periodo vigente actualizado.';await load(page.value)}catch(v){error.value=message(v)}}
function openProcess(item:PeriodoContable,next:'aperturar'|'cerrar'){selected.value=item;action.value=next;processForm.generar_asiento=false;processForm.fecha=new Date().toISOString().slice(0,10);processForm.glosa='';processModal.value=true}
async function runProcess(){if(!selected.value)return;saving.value=true;try{await procesarPeriodo(selected.value.id,action.value,{...processForm});processModal.value=false;success.value=`Periodo ${action.value==='aperturar'?'aperturado':'cerrado'} correctamente.`;await load(page.value)}catch(v){error.value=message(v)}finally{saving.value=false}}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Periodos contables</nav><header class="hero"><div class="mark">PC</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Periodos contables</h1><p>Administra periodos, vigencia y ciclos de apertura y cierre contable.</p></div><strong>{{total}} periodos</strong><button @click="open()">+ Nuevo periodo</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por código o descripción"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando periodos…</div><div v-else-if="!rows.length" class="empty">No se encontraron periodos contables.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Descripción</th><th>Estado</th><th>Vigente</th><th>Proceso</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td><span v-if="item.vigente" class="current">Vigente</span><button v-else class="link" @click="current(item)">Marcar vigente</button></td><td><span class="process" :class="item.estado_proceso.toLowerCase()">{{item.estado_proceso_label||item.estado_proceso}}</span></td><td class="actions"><button v-if="item.estado_proceso==='CREADO'" class="open" @click="openProcess(item,'aperturar')">Aperturar</button><button v-if="item.estado_proceso==='ABIERTO'" class="close" @click="openProcess(item,'cerrar')">Cerrar</button><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>PERIODO CONTABLE</small><h2>{{editing?'Editar':'Nuevo'}} periodo</h2></div><button type="button" @click="modal=false">×</button></header><label>Código *<input v-model="form.codigo" maxlength="20" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Descripción *<input v-model="form.descripcion" maxlength="150"></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div>
<div v-if="processModal" class="backdrop" @mousedown.self="processModal=false"><form class="dialog" @submit.prevent="runProcess"><header><div><small>PROCESO CONTABLE</small><h2>{{action==='aperturar'?'Aperturar':'Cerrar'}} {{selected?.codigo}}</h2></div><button type="button" @click="processModal=false">×</button></header><label>Fecha<input v-model="processForm.fecha" type="date"></label><label>Glosa<textarea v-model="processForm.glosa" rows="3"/></label><label class="check"><input v-model="processForm.generar_asiento" type="checkbox"> Generar asiento contable</label><footer><button type="button" class="soft" @click="processModal=false">Cancelar</button><button :disabled="saving">Confirmar</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;color:var(--accent);font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters{margin-top:10px;padding:13px;display:flex;gap:7px;border-radius:9px;background:#fff}.filters input,.dialog input,.dialog textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.55rem}.filters input{margin-right:auto}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse;font-size:.53rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.ok,.bad,.current,.process{padding:4px 7px;border-radius:10px;font-size:.43rem}.ok,.current,.abierto{color:#287154;background:#e6f7ee}.bad,.cerrado{color:#9d4046;background:#fdebed}.creado{color:#79500b;background:#fff0cf}.link{border:0;color:var(--accent);background:none;font-size:.48rem}.actions{display:flex;gap:4px}.actions button{padding:6px 7px;border:0;border-radius:5px;font-size:.45rem}.open{color:#287154;background:#e6f7ee}.close{color:#9d4046;background:#fdebed}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(520px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 15px;font-size:.9rem}.dialog header button{color:#59666c;background:none;font-size:1.1rem}.dialog label{display:grid;margin-top:10px;font-size:.52rem}.dialog input,.dialog textarea{margin-top:5px}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto;margin:0}.dialog footer{margin-top:17px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:720px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters input{flex-basis:100%}}
</style>
